CREATE OR REPLACE FUNCTION editing_protocol_fence() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE protocol text; BEGIN SELECT p.protocol INTO STRICT protocol FROM editing_protocol p WHERE singleton FOR SHARE; IF protocol='paragraph-body-v3' AND current_setting('airdesign.history_protocol',true) IS DISTINCT FROM 'paragraph-body-v3' THEN RAISE EXCEPTION 'editing-protocol-mismatch' USING ERRCODE='55000'; END IF; RETURN NULL; END $$
